import { Component } from "solid-js";

import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import style from "./mini-map-legend-panel.scss?url";

const hexIconUrl = "blp:bg_hex-icon.png";
interface MiniMapPlotLegendProps {
	color: string;
	text: string;
}
const MiniMapPlotLegendComponent: Component<MiniMapPlotLegendProps> = (props) => {
	return (
		<div class="flex flex-row items-center legend-description">
			<div
				class="size-12 bg-contain bg-no-repeat bg-center"
				style={{
					"background-image": `url(${hexIconUrl})`,
					// eslint-disable-next-line solid/style-prop
					"fxs-background-image-tint": props.color,
				}}
			/>
			<div class="flex-auto">
				<L10n.Compose text={props.text} />
			</div>
		</div>
	);
};

export const MiniMapPlotLegend = ComponentRegistry.register({
	name: "MiniMapPlotLegend",
	createInstance: MiniMapPlotLegendComponent,
	images: [hexIconUrl],
	styles: [style],
});
